{
  "name": "opencode-flema-engram-sidebar",
  "version": "0.4.5",
  "description": "Read-only Engram viewers for OpenCode and Pi/Gentle Shell with ODD-first project context and an optional MCP stdio adapter",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/sidebar/plugin.d.ts",
      "import": "./dist/sidebar/plugin.js"
    },
    "./core": {
      "types": "./dist/core.d.ts",
      "import": "./dist/core.js"
    },
    "./pi": {
      "types": "./dist/pi.d.ts",
      "import": "./dist/pi.js"
    }
  },
  "pi": {
    "extensions": [
      "./dist/pi.js"
    ]
  },
  "bin": {
    "flema-engram": "dist/maintenance.js",
    "mcp-flema-engram": "dist/stdio.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest --coverage",
    "mcp": "tsx src/stdio.ts",
    "verify:package": "node scripts/package-verifier.mjs",
    "prepublishOnly": "npm run typecheck && npm test && npm run build && npm run verify:package"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-sidebar",
    "tui",
    "sidebar",
    "engram",
    "local-first",
    "developer-tools",
    "odd",
    "pi",
    "gentle-shell",
    "memory",
    "mcp",
    "pi-package"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/oniricosistemas/flema-engram.git"
  },
  "bugs": {
    "url": "https://github.com/oniricosistemas/flema-engram/issues"
  },
  "homepage": "https://github.com/oniricosistemas/flema-engram#readme",
  "engines": {
    "node": ">=22",
    "opencode": ">=1.18.25"
  },
  "peerDependencies": {
    "@earendil-works/pi-tui": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-tui": {
      "optional": true
    }
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.31.0",
    "@opencode-ai/plugin": "^1.18.25",
    "@opentui/solid": "0.5.9",
    "solid-js": "^1.9.12",
    "tsx": "^4.23.13",
    "zod": "^3.25.0"
  },
  "devDependencies": {
    "@earendil-works/pi-tui": ">=1.2.0",
    "@types/node": "^22.0.0",
    "@vitest/coverage-v8": "5.0.4",
    "typescript": "^5.8.0",
    "vitest": "5.0.4",
    "yaml": "^2.9.0"
  }
}
